import time

def check_token(submitted_value, identity, records):
    record = records.get(identity)

    if not record:
        return False

    stored_value = record.get('token')
    expiry_ts = record.get('expires_at')

    if stored_value is None or expiry_ts is None:
        return False

    if submitted_value == stored_value and time.time() < expiry_ts:
        return True

    return False
